import os,re
for r,d,f in os.walk('src'):
  for file in f:
    if file.endswith('.py'):
      path=os.path.join(r,file)
      with open(path,'r') as t: lines=t.readlines()
      new=[]
      for line in lines:
        if re.match(r'\s*\w+:\s*\w+\s*=\s*.*', line):
          new.append('# ' + line)
        else:
          new.append(line)
      with open(path,'w') as t: t.writelines(new)
print('commented')
